import{_ as e,o as t,c as s,ak as a}from"./chunks/framework.sV-XtlWr.js";const g=JSON.parse('{"title":"Authentication","description":"Turn on sign-in and roles, create the first administrator, configure Google and GitHub OAuth, and manage user accounts.","frontmatter":{"title":"Authentication","description":"Turn on sign-in and roles, create the first administrator, configure Google and GitHub OAuth, and manage user accounts.","lang":"en-US","head":[["link",{"rel":"canonical","href":"https://piwitests.dev/operate/authentication.html"}],["meta",{"property":"og:url","content":"https://piwitests.dev/operate/authentication.html"}],["meta",{"property":"og:title","content":"Authentication | Piwi Dashboard"}],["meta",{"property":"og:description","content":"Turn on sign-in and roles, create the first administrator, configure Google and GitHub OAuth, and manage user accounts."}]]},"headers":[],"relativePath":"operate/authentication.md","filePath":"operate/authentication.md","lastUpdated":1790454954000}'),n={name:"operate/authentication.md"};function o(r,i,h,l,d,p){return t(),s("div",null,[...i[0]||(i[0]=[a(`<h1 id="authentication" tabindex="-1">Authentication <a class="header-anchor" href="#authentication" aria-label="Permalink to &quot;Authentication&quot;">​</a></h1><p>The dashboard supports optional sign-in with role-based access control. Authentication is <strong>disabled by default</strong>: every endpoint then behaves as a single administrator. Turn it on before anyone else can reach the instance; the <a href="./production-checklist.html">production checklist</a> lists the rest of what to set.</p><h2 id="roles" tabindex="-1">Roles <a class="header-anchor" href="#roles" aria-label="Permalink to &quot;Roles&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Role</th><th>Description</th></tr></thead><tbody><tr><td><strong>Administrator</strong></td><td>Full access to every project and feature — editing projects, managing users, and deleting runs. Never restricted by project access.</td></tr><tr><td><strong>Reporter</strong></td><td>Submits results (<code>/api/test-runs/submit</code>, <code>/api/test-runs/upload</code>) and can triage, but only for the <strong>projects it&#39;s assigned to</strong>.</td></tr><tr><td><strong>User</strong></td><td>Read-only access to the <strong>projects it&#39;s assigned to</strong>.</td></tr></tbody></table><p>Administrators always see everything. <strong>Reporter</strong> and <strong>User</strong> accounts are additionally scoped by <a href="./project-access.html">project access</a>: they only see and act on the projects assigned to them.</p><h2 id="enabling-authentication" tabindex="-1">Enabling authentication <a class="header-anchor" href="#enabling-authentication" aria-label="Permalink to &quot;Enabling authentication&quot;">​</a></h2><ol><li><p>Set these variables wherever you configure the server (the container&#39;s environment, <code>.env</code>, or your host&#39;s dashboard):</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">PIWI_AUTH_ENABLED</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">true</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">PIWI_AUTH_SECRET</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">your-auth-secret-here</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  # signs session cookies</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">PIWI_SECRET_KEY</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">your-secret-key-here</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # encrypts stored credentials (AI keys, SCM tokens)</span></span></code></pre></div><p>Generate a strong random value for each secret (run it twice):</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -e</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;console.log(require(&#39;node:crypto&#39;).randomBytes(32).toString(&#39;hex&#39;))&quot;</span></span></code></pre></div></li><li><p>Restart the server. It refuses to start with authentication on and no <code>PIWI_AUTH_SECRET</code>.</p></li></ol><h2 id="initial-setup" tabindex="-1">Initial setup <a class="header-anchor" href="#initial-setup" aria-label="Permalink to &quot;Initial setup&quot;">​</a></h2><p>When authentication is enabled and no users exist yet, opening the dashboard lands on the login page, which shows a <strong>Create the first admin account</strong> form in place of the sign-in form. Fill it in and you are signed in as the administrator, with no API call needed.</p><p>For provisioning an instance from a script, the same step is available as an API call:</p><div class="vp-code-group vp-adaptive-theme"><div class="tabs"><input type="radio" name="group-0jgzw" id="tab-V62J0ub" checked><label data-title="Linux / macOS" for="tab-V62J0ub">Linux / macOS</label><input type="radio" name="group-0jgzw" id="tab-pQoB1Kw"><label data-title="Windows (PowerShell)" for="tab-pQoB1Kw">Windows (PowerShell)</label></div><div class="blocks"><div class="language-bash vp-adaptive-theme active"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> POST</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://localhost:3000/api/auth/setup</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Content-Type: application/json&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;{</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &quot;username&quot;: &quot;admin&quot;,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &quot;password&quot;: &quot;your-secure-password&quot;,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &quot;name&quot;: &quot;Administrator&quot;</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  }&#39;</span></span></code></pre></div><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$body </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> @</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{ username </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;admin&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">; password </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;your-secure-password&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">; name </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;Administrator&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> } </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">|</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> ConvertTo-Json</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Invoke-RestMethod</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Method Post </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Uri http:</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">//</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">localhost:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">3000</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">api</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">auth</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">setup </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">\`</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">ContentType </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;application/json&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Body $body</span></span></code></pre></div></div></div><p>Both routes go through <code>POST /api/auth/setup</code>, which is only available while the users table is empty and is rate-limited per client address.</p><h2 id="logging-in" tabindex="-1">Logging in <a class="header-anchor" href="#logging-in" aria-label="Permalink to &quot;Logging in&quot;">​</a></h2><p>Sign in at <code>/login</code>. Sessions are stored in encrypted cookies and last for 7 days.</p><h2 id="oauth-google-github" tabindex="-1">OAuth (Google, GitHub) <a class="header-anchor" href="#oauth-google-github" aria-label="Permalink to &quot;OAuth (Google, GitHub)&quot;">​</a></h2><p>Users can sign in with Google or GitHub instead of a username and password.</p><h3 id="configuring-oauth" tabindex="-1">Configuring OAuth <a class="header-anchor" href="#configuring-oauth" aria-label="Permalink to &quot;Configuring OAuth&quot;">​</a></h3><ol><li><p><strong>Register an OAuth application</strong> with each provider you want to use:</p><ul><li><strong>Google</strong>: Go to the <a href="https://console.cloud.google.com/apis/credentials" target="_blank" rel="noreferrer">Google Cloud Console</a>, create an OAuth 2.0 Client ID, and add <code>https://your-domain.com/api/auth/oauth/google/callback</code> to the authorized redirect URIs.</li><li><strong>GitHub</strong>: Go to <strong>Settings → Developer settings → OAuth Apps</strong> on GitHub, create a new OAuth app, and set the callback URL to <code>https://your-domain.com/api/auth/oauth/github/callback</code>.</li></ul></li><li><p><strong>Set the credentials</strong> alongside the other variables:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">PIWI_OAUTH_GOOGLE_CLIENT_ID</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">your-google-client-id</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">PIWI_OAUTH_GOOGLE_CLIENT_SECRET</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">your-google-client-secret</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">PIWI_OAUTH_GITHUB_CLIENT_ID</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">your-github-client-id</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">PIWI_OAUTH_GITHUB_CLIENT_SECRET</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">your-github-client-secret</span></span></code></pre></div><p>Only configure the providers you actually want to use. OAuth buttons appear automatically on the login page when both a provider&#39;s <code>CLIENT_ID</code> and <code>CLIENT_SECRET</code> are set.</p></li><li><p><strong>Restart the server.</strong> The login page now shows <strong>Sign in with Google</strong> and/or <strong>Sign in with GitHub</strong> buttons above the password form.</p></li></ol><blockquote><p><strong>Behind a reverse proxy:</strong> set <code>PIWI_SITE_URL</code> to your public URL (e.g. <code>https://piwi.example.com</code>). The OAuth <code>redirect_uri</code> is built from it, so it stays consistent with the value you registered even when the proxy rewrites the request host. Without it the redirect URI is inferred from the incoming request.</p></blockquote><h3 id="restricting-who-can-sign-in-allowlists" tabindex="-1">Restricting who can sign in (allowlists) <a class="header-anchor" href="#restricting-who-can-sign-in-allowlists" aria-label="Permalink to &quot;Restricting who can sign in (allowlists)&quot;">​</a></h3><p>By default any account at a configured provider can sign in (and a new <strong>user</strong>-role account is created). To restrict access:</p><ul><li><strong><code>PIWI_OAUTH_ALLOWED_DOMAINS</code></strong> — comma-separated email domains (e.g. <code>example.com,acme.org</code>). Only <strong>verified</strong> provider emails in these domains may sign in. Applies to all providers — ideal for limiting Google Workspace sign-in to your company domain.</li><li><strong><code>PIWI_OAUTH_GITHUB_ALLOWED_ORGS</code></strong> — comma-separated GitHub org logins. The user must be a member of at least one. Enabling this requests the <code>read:org</code> scope so membership (including private) can be checked.</li></ul><p>Rejected sign-ins are returned to the login page with an explanatory message.</p><h3 id="account-linking" tabindex="-1">Account linking <a class="header-anchor" href="#account-linking" aria-label="Permalink to &quot;Account linking&quot;">​</a></h3><p>A first sign-in with a provider either links an existing account or creates a new one:</p><ul><li>If a user with the same <strong>verified</strong> email exists (and isn&#39;t already linked to a <em>different</em> provider), the existing account is linked to the provider. Linking needs proof on both sides: the provider must assert the email is verified, <strong>and</strong> the local account must have verified it too (through the verification link, an accepted invite, or an earlier provider sign-in). This stops an attacker-controlled public email, or an address someone typed into their own profile, from capturing another person&#39;s sign-in.</li><li>If the matching account has <strong>not</strong> verified the address, the sign-in is refused with an explanatory message instead of being linked. The account&#39;s owner signs in with its password (or accepts their invite first) and connects the provider from <strong>Settings → Account</strong>.</li><li>If the matching account is <strong>already linked to a different provider</strong>, the sign-in is refused: one provider is linked per account, so sign in with the original method instead.</li><li>Otherwise, a new user is created with the <strong>User</strong> role and no password, so it always signs in through its provider. GitHub accounts with no verified primary email always get a new account.</li></ul><p>The dashboard does not keep the provider&#39;s tokens: the access token is used once to read the profile, then discarded. OAuth is not available in demo mode.</p><h3 id="connecting-disconnecting-a-provider" tabindex="-1">Connecting / disconnecting a provider <a class="header-anchor" href="#connecting-disconnecting-a-provider" aria-label="Permalink to &quot;Connecting / disconnecting a provider&quot;">​</a></h3><p>Signed-in users can link a provider explicitly from <strong>Settings → Account → Connected accounts</strong>:</p><ul><li><strong>Connect</strong> starts the OAuth flow in &quot;link&quot; mode and attaches the provider identity to the current account (rather than creating a new one). A provider identity already linked to another account is refused.</li><li><strong>Disconnect</strong> removes the link. It&#39;s only allowed when the account also has a password set, so a provider-only user can&#39;t lock themselves out — set a password first.</li></ul><h2 id="user-management" tabindex="-1">User management <a class="header-anchor" href="#user-management" aria-label="Permalink to &quot;User management&quot;">​</a></h2><p>Administrators manage accounts under <strong>Settings → Users</strong> (<code>/settings/users</code>). <strong>Add user</strong> creates one with a username, password, role and optional display name.</p><h3 id="changing-a-role" tabindex="-1">Changing a role <a class="header-anchor" href="#changing-a-role" aria-label="Permalink to &quot;Changing a role&quot;">​</a></h3><p>Each row&#39;s <strong>Role</strong> column is an inline selector — pick a new role to reassign it immediately (the user&#39;s active sessions are revoked so the change takes effect at once). This is the only way to change an existing account&#39;s role, including accounts created through <a href="#oauth-google-github">OAuth</a>, which always start with the <strong>User</strong> role. The <strong>last remaining administrator cannot be demoted</strong>, so an instance can never be left without one.</p><p>Which projects a Reporter or User can open is <a href="./project-access.html">project access</a>, and the keys that let CI and scripts sign in are <a href="./api-keys.html">API keys</a>.</p><h2 id="disabling-authentication" tabindex="-1">Disabling authentication <a class="header-anchor" href="#disabling-authentication" aria-label="Permalink to &quot;Disabling authentication&quot;">​</a></h2><p>Set <code>PIWI_AUTH_ENABLED=false</code>, or remove the variable, and restart the server. Every endpoint is then accessible without authentication.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./project-access.html">Project access</a>: which projects each Reporter and User can open</li><li><a href="./api-keys.html">API keys</a>: authenticating the reporter, CI and scripts</li><li><a href="./production-checklist.html">Production checklist</a>: the secrets, TLS and proxy settings to go with it</li><li><a href="/reference/configuration.html#authentication">Configuration reference</a>: every authentication and OAuth variable</li></ul>`,39)])])}const u=e(n,[["render",o]]);export{g as __pageData,u as default};
